// Formula parsing and evaluation. The AST shape is private to this module.
import { parseAddr, toAddr } from "./addr.mjs";

const TOKEN = /\s*(?:(\d+\.?\d*(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?)|"((?:[^"]|"")*)"|([A-Za-z_][A-Za-z0-9_.]*)(?=\s*\()|(\$?[A-Za-z]{1,3}\$?\d+)(?![A-Za-z0-9_.(])|(TRUE|FALSE)(?![A-Za-z0-9_.(])|(<>|<=|>=|[=<>&+\-*\/^(),:]))/iy;

function tokenize(text) {
  const out = [];
  let pos = 0;
  for (;;) {
    TOKEN.lastIndex = pos;
    if (/^\s*$/.test(text.slice(pos))) return out;
    const m = TOKEN.exec(text);
    if (!m) throw new SyntaxError(`unexpected input at ${pos}: ${text.slice(pos).trim().slice(0, 10)}`);
    pos = TOKEN.lastIndex;
    if (m[1] !== undefined) out.push({ k: "num", v: Number(m[1]) });
    else if (m[2] !== undefined) out.push({ k: "str", v: m[2].replace(/""/g, '"') });
    else if (m[3] !== undefined) out.push({ k: "name", v: m[3].toUpperCase() });
    else if (m[4] !== undefined) out.push({ k: "ref", v: m[4] });
    else if (m[5] !== undefined) out.push({ k: "bool", v: m[5].toUpperCase() === "TRUE" });
    else out.push({ k: "op", v: m[6] });
  }
}

const normAddr = (text) => {
  let a;
  try { a = parseAddr(text); } catch { throw new SyntaxError(`bad reference: ${text}`); }
  return toAddr(a.col, a.row);
};

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const isOp = (v) => toks[i] && toks[i].k === "op" && toks[i].v === v;
  const expect = (v) => {
    if (!isOp(v)) throw new SyntaxError(`expected ${v}`);
    i++;
  };
  const level = (ops, next) => () => {
    let l = next();
    while (toks[i] && toks[i].k === "op" && ops.includes(toks[i].v)) {
      const op = toks[i++].v;
      l = { t: "bin", op, l, r: next() };
    }
    return l;
  };
  const primary = () => {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    switch (tok.k) {
      case "num": return { t: "lit", v: tok.v };
      case "str": return { t: "lit", v: tok.v };
      case "bool": return { t: "lit", v: tok.v };
      case "ref": {
        const a = normAddr(tok.v);
        if (!isOp(":")) return { t: "ref", addr: a };
        i++;
        const n = toks[i++];
        if (!n || n.k !== "ref") throw new SyntaxError("bad range");
        const p = parseAddr(a), q = parseAddr(normAddr(n.v));
        const addrs = [];
        for (let r = Math.min(p.row, q.row); r <= Math.max(p.row, q.row); r++)
          for (let c = Math.min(p.col, q.col); c <= Math.max(p.col, q.col); c++) addrs.push(toAddr(c, r));
        return { t: "range", addrs };
      }
      case "name": {
        expect("(");
        const args = [];
        if (!isOp(")")) {
          for (;;) {
            args.push(comparison());
            if (isOp(",")) i++;
            else break;
          }
        }
        expect(")");
        return { t: "call", name: tok.v, args };
      }
      case "op":
        if (tok.v === "(") {
          const e = comparison();
          expect(")");
          return e;
        }
      // fallthrough
      default: throw new SyntaxError(`unexpected ${tok.v}`);
    }
  };
  // Unary minus binds tighter than ^, so the operand of ^ is a unary expression.
  const unary = () => {
    if (isOp("-") || isOp("+")) return { t: "un", op: toks[i++].v, x: unary() };
    return primary();
  };
  const power = level(["^"], unary);
  const product = level(["*", "/"], power);
  const sum = level(["+", "-"], product);
  const concat = level(["&"], sum);
  const comparison = level(["=", "<>", "<", ">", "<=", ">="], concat);
  const ast = comparison();
  if (i < toks.length) throw new SyntaxError(`unexpected ${toks[i].v}`);
  return ast;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": n.addrs.forEach((a) => seen.add(a)); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "un": walk(n.x); break;
      case "call": n.args.forEach(walk); break;
    }
  };
