const isErr = (v) => typeof v === "string" && v[0] === "#";
const NUM_RE = /^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$/i;

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "string") {
    const s = v.trim();
    return NUM_RE.test(s) ? Number(s) : "#VALUE!";
  }
  return v;
}

function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "number") return v !== 0;
  if (typeof v === "string") {
    const u = v.toUpperCase();
    return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
  }
  return v;
}

function toText(v) {
  if (isErr(v)) return v;
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : typeof b === "boolean" ? false : 0;
  if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function roundTo(x, d) {
  const shift = (n, k) => {
    const [m, e = "0"] = String(n).split("e");
    return Number(`${m}e${Number(e) + k}`);
  };
  const r = shift(Math.round(shift(Math.abs(x), d)), -d);
  return x < 0 ? -r : r;
}

const ARITY = {
  IF: [2, 3], NOT: [1, 1], ROUND: [2, 2], ABS: [1, 1], LEN: [1, 1], UPPER: [1, 1], LOWER: [1, 1],
  AND: [1, Infinity], OR: [1, Infinity], SUM: [0, Infinity], AVERAGE: [0, Infinity], MIN: [0, Infinity],
  MAX: [0, Infinity], COUNT: [0, Infinity], CONCAT: [0, Infinity],
};

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "lit": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const x = toNum(ev(n.x));
        if (typeof x === "string") return x;
        return n.op === "-" ? -x : x;
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  function binary(n) {
    const a = ev(n.l);
    if (isErr(a)) return a;
    const b = ev(n.r);
    if (isErr(b)) return b;
    if (n.op === "&") return toText(a) + toText(b);
    if ("= <> < > <= >=".split(" ").includes(n.op)) {
      const c = compare(a, b);
      switch (n.op) {
        case "=": return c === 0;
        case "<>": return c !== 0;
        case "<": return c < 0;
        case ">": return c > 0;
        case "<=": return c <= 0;
        default: return c >= 0;
      }
    }
    const x = toNum(a);
    if (typeof x === "string") return x;
    const y = toNum(b);
    if (typeof y === "string") return y;
    let r;
    switch (n.op) {
      case "+": r = x + y; break;
      case "-": r = x - y; break;
      case "*": r = x * y; break;
      case "/":
        if (y === 0) return "#DIV/0!";
        r = x / y;
        break;
      default: r = x ** y;
    }
    return Number.isFinite(r) ? r : "#NUM!";
  }

  // Visits arguments in order; ranges yield their cell values, direct args their value. Returns an error or undefined.
  function each(args, onRange, onDirect) {
    for (const a of args) {
      if (a.t === "range") {
        for (const addr of a.addrs) {
          const v = lookup(addr);
          const e = onRange(v);
          if (e !== undefined) return e;
        }
      } else {
        const e = onDirect(ev(a));
        if (e !== undefined) return e;
      }
    }
  }

  function call(n) {
    const ar = ARITY[n.name];
    if (!ar) return "#NAME?";
    const args = n.args;
    if (args.length < ar[0] || args.length > ar[1]) return "#VALUE!";
    const one = (f) => {
      const v = ev(args[0]);
      return isErr(v) ? v : f(v);
    };
    switch (n.name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": {
        const nums = [];
        const err = each(args,
          (v) => { if (isErr(v)) return v; if (typeof v === "number") nums.push(v); },
          (v) => { const x = toNum(v); if (typeof x === "string") return x; nums.push(x); });
        if (err !== undefined) return err;
        if (n.name === "SUM") return finite(nums.reduce((s, x) => s + x, 0));
        if (n.name === "AVERAGE") return nums.length ? finite(nums.reduce((s, x) => s + x, 0) / nums.length) : "#DIV/0!";
        if (!nums.length) return 0;
        return n.name === "MIN" ? Math.min(...nums) : Math.max(...nums);
      }
      case "COUNT": {
        let c = 0;
        each(args, (v) => { if (typeof v === "number") c++; }, (v) => { if (typeof v === "number") c++; });
        return c;
      }
      case "IF": {
        const c = toBool(ev(args[0]));
        if (typeof c === "string") return c;
        if (c) return ev(args[1]);
        return args.length > 2 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        const vals = [];
        const err = each(args,
          (v) => { if (isErr(v)) return v; if (typeof v === "number" || typeof v === "boolean") vals.push(toBool(v)); },
          (v) => { const b = toBool(v); if (typeof b === "string") return b; vals.push(b); });
        if (err !== undefined) return err;
        return n.name === "AND" ? vals.every(Boolean) : vals.some(Boolean);
      }
      case "NOT": return one((v) => { const b = toBool(v); return typeof b === "string" ? b : !b; });
      case "ABS": return one((v) => { const x = toNum(v); return typeof x === "string" ? x : Math.abs(x); });
      case "ROUND": {
        const x = toNum(ev(args[0]));
        if (typeof x === "string") return x;
        const d = toNum(ev(args[1]));
        if (typeof d === "string") return d;
        return finite(roundTo(x, Math.trunc(d)));
      }
      case "LEN": return one((v) => toText(v).length);
      case "UPPER": return one((v) => toText(v).toUpperCase());
      case "LOWER": return one((v) => toText(v).toLowerCase());
      case "CONCAT": {
        let s = "";
        const err = each(args,
          (v) => { if (isErr(v)) return v; s += toText(v); },
          (v) => { if (isErr(v)) return v; s += toText(v); });
        return err !== undefined ? err : s;
      }
    }
  }

  const finite = (r) => (Number.isFinite(r) ? r : "#NUM!");
  return ev(ast);
}
