// Recalculation: cell values, dependency order and dependents.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "") return null;
  const t = raw.trim();
  if (t !== "") {
    const n = Number(t);
    if (Number.isFinite(n)) return n;
  }
  const u = raw.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

const norm = (addr) => { const a = parseAddr(addr); return toAddr(a.col, a.row); };

// Parses every formula and finds strongly connected components (iterative Tarjan).
// `order` lists formula cells with dependencies first; `cyclic` holds cells on a cycle.
function analyze(sheet) {
  const asts = new Map(), deps = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    let ast = null;
    try { ast = parseFormula(raw.slice(1)); } catch { /* #ERROR! */ }
    asts.set(addr, ast);
    deps.set(addr, ast ? refsOf(ast).filter((r) => asts.has(r) || sheet.cells.get(r)?.startsWith("=")) : []);
  }
  for (const [a, d] of deps) deps.set(a, d.filter((r) => deps.has(r)));
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [];
  const order = [], cyclic = new Set();
  let counter = 0;
  for (const root of deps.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, counter); low.set(root, counter++); stack.push(root); onStack.add(root);
    while (work.length) {
      const frame = work[work.length - 1];
      const [v, i] = frame;
      const d = deps.get(v);
      if (i < d.length) {
        frame[1]++;
        const w = d[i];
        if (!index.has(w)) {
          index.set(w, counter); low.set(w, counter++); stack.push(w); onStack.add(w);
          work.push([w, 0]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          if (comp.length > 1 || deps.get(v).includes(v)) comp.forEach((c) => cyclic.add(c));
          order.push(...comp);
        }
      }
    }
  }
  return { asts, deps, order, cyclic };
}

export function computeAll(sheet) {
  const { asts, order, cyclic } = analyze(sheet);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!asts.has(addr)) values.set(addr, valueOf(raw));
  const lookup = (a) => values.get(norm(a)) ?? null;
  for (const addr of order) {
    const ast = asts.get(addr);
    values.set(addr, cyclic.has(addr) ? "#CYCLE!" : ast ? evaluate(ast, lookup) : "#ERROR!");
  }
  const out = new Map();
  for (const addr of sheet.cells.keys()) out.set(addr, values.get(addr));
  return out;
}

export function dependents(sheet, addr) {
  addr = norm(addr);
  const { deps, cyclic } = analyze(sheet);
  const rev = new Map();
  for (const [a, d] of deps) for (const r of d) {
    if (!rev.has(r)) rev.set(r, []);
    rev.get(r).push(a);
  }
  const seen = new Set([addr]), queue = [addr], set = new Set();
  for (let i = 0; i < queue.length; i++) {
    for (const a of rev.get(queue[i]) ?? []) {
      if (seen.has(a)) continue;
      seen.add(a);
      queue.push(a);
      if (!cyclic.has(a)) set.add(a);
    }
  }
  const pending = new Map(), next = new Map();
  for (const a of set) {
    pending.set(a, 0);
  }
  for (const a of set) for (const r of new Set(deps.get(a))) if (set.has(r)) {
    pending.set(a, pending.get(a) + 1);
    if (!next.has(r)) next.set(r, []);
    next.get(r).push(a);
  }
  const key = (a) => { const p = parseAddr(a); return p.row * 1e6 + p.col; };
  const heap = [];
  const push = (a) => {
    const k = key(a);
    let i = heap.push([k, a]) - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p][0] <= heap[i][0]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && heap[c][0] < heap[m][0]) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top[1];
  };
  for (const [a, n] of pending) if (n === 0) push(a);
  const result = [];
  while (heap.length) {
    const a = pop();
    result.push(a);
    for (const b of next.get(a) ?? []) {
      pending.set(b, pending.get(b) - 1);
      if (pending.get(b) === 0) push(b);
    }
  }
  return result;
}
