// Sorting and pivoting of cell ranges.
import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { valueOf } from "./recalc.mjs";
import { setCell, getCell } from "./sheet.mjs";

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, then strings (case-insensitive), then booleans.
function compareValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function parseRange(range) {
  const [s, e] = range.split(":");
  const a = parseAddr(s), b = parseAddr(e ?? s);
  return { c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col), r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row) };
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push({ raws, vals: raws.map(valueOf) });
  }
  const cols = keys.map((k) => ({ i: colIndex(k.col) - c1, desc: !!k.desc }));
  rows.sort((x, y) => {
    for (const { i, desc } of cols) {
      const a = x.vals[i], b = y.vals[i];
      if (a == null || b == null) {
        if (a == null && b == null) continue;
        return a == null ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return desc ? -d : d;
    }
    return 0;
  });
  rows.forEach(({ raws }, n) => raws.forEach((raw, j) => setCell(sheet, toAddr(c1 + j, start + n), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const find = (name) => {
    for (let c = c1; c <= c2; c++) if (values.get(toAddr(c, r1)) === name) return c;
    throw new Error(`no such column: ${name}`);
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  let blank = null;
  for (let r = r1 + 1; r <= r2; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    const v = values.get(toAddr(vc, r)) ?? null;
    let g;
    if (k == null) g = blank ??= { key: "(blank)", items: [] };
    else {
      g = groups.get(k);
      if (!g) groups.set(k, (g = { key: k, items: [] }));
    }
    g.items.push(v);
  }
  const aggregate = (items) => {
    if (agg === "count") return items.filter((v) => v != null).length;
    const nums = items.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, n) => s + n, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, n) => s + n, 0) / nums.length;
    if (agg === "min") return Math.min(...nums);
    if (agg === "max") return Math.max(...nums);
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const list = [...groups.values()].sort((x, y) => compareValues(x.key, y.key));
  if (blank) list.push(blank);
  return list.map((g) => ({ key: g.key, value: aggregate(g.items) }));
}
