// Subset of spreadsheet number formats.

function plain(n) {
  // Non-negative finite number -> [integer digits, fraction digits] without exponent notation.
  const s = String(n);
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(s);
  let int = m[1];
  let frac = m[2] || "";
  const exp = m[3] ? Number(m[3]) : 0;
  if (exp > 0) {
    frac = frac.padEnd(exp, "0");
    int += frac.slice(0, exp);
    frac = frac.slice(exp);
  } else if (exp < 0) {
    int = int.padStart(-exp + 1, "0");
    frac = int.slice(int.length + exp) + frac;
    int = int.slice(0, int.length + exp);
  }
  return [int.replace(/^0+/, ""), frac];
}

// Round digit strings half away from zero to d decimals.
function roundDigits(int, frac, d) {
  const up = frac.length > d && frac[d] >= "5";
  let all = BigInt((int + frac.slice(0, d).padEnd(d, "0")) || "0");
  if (up) all += 1n;
  const s = all.toString().padStart(d + 1, "0");
  return [s.slice(0, s.length - d).replace(/^0+/, ""), s.slice(s.length - d)];
}

function tokenize(section) {
  const toks = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const j = section.indexOf('"', i + 1);
      const end = j < 0 ? section.length : j;
      toks.push({ lit: section.slice(i + 1, end) });
      i = end;
    } else if (c === "\\") {
      if (i + 1 < section.length) toks.push({ lit: section[++i] });
    } else if ((c === "E" || c === "e") && (section[i + 1] === "+" || section[i + 1] === "-")) {
      let j = i + 2;
      while (section[j] === "0" || section[j] === "#") j++;
      toks.push({ exp: section[i + 1], min: (section.slice(i + 2, j).match(/0/g) || []).length, up: c });
      i = j - 1;
    } else if (c === "%") {
      toks.push({ pct: true });
    } else if ("0#,.".includes(c)) {
      toks.push({ ph: c });
    } else {
      toks.push({ lit: c });
    }
  }
  return toks;
}

function splitSections(pattern) {
  const out = [];
  let cur = "";
  let q = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === "\\" && !q) { cur += c + (pattern[++i] ?? ""); continue; }
    if (c === '"') q = !q;
    if (c === ";" && !q) { out.push(cur); cur = ""; } else cur += c;
  }
  out.push(cur);
  return out;
}

function render(abs, toks) {
  const pct = toks.some((t) => t.pct);
  let [int, frac] = plain(abs);
  if (pct) {
    frac = frac.padEnd(2, "0");
    int = (int + frac.slice(0, 2)).replace(/^0+/, "");
    frac = frac.slice(2);
  }
  const first = toks.findIndex((t) => t.ph);
  const last = toks.map((t) => !!t.ph).lastIndexOf(true);
  const expTok = toks.find((t) => t.exp);
  const region = first < 0 ? [] : toks.slice(first, last + 1).filter((t) => t.ph);
  const dot = region.findIndex((t) => t.ph === ".");
  const intPh = dot < 0 ? region : region.slice(0, dot);
  const fracPh = dot < 0 ? [] : region.slice(dot + 1).filter((t) => t.ph !== ",");
  const d = fracPh.length;
  const minInt = intPh.filter((t) => t.ph === "0").length;
  const intDigitsPh = intPh.map((t) => t.ph);
  const group = intDigitsPh.some((p, i) => p === "," && i > 0 && intDigitsPh.slice(i).some((x) => x !== ","));

  let exponent = null;
  if (expTok) {
    let digits = (int + frac).replace(/^0+/, "");
    let e = digits ? int.length - 1 : 0;
    if (!int) e = digits ? -(frac.length - frac.replace(/^0+/, "").length) - 1 : 0;
    if (!digits) digits = "0";
    const all = digits.padEnd(d + 1, "0");
    let [i2, f2] = roundDigits(all.slice(0, 1), all.slice(1), d);
    if (i2.length > 1) { e++; [i2, f2] = roundDigits("1", "", d); }
    int = i2 || "0";
    frac = f2;
    exponent = e;
  } else {
    [int, frac] = roundDigits(int, frac, d);
  }
  const zero = !/[1-9]/.test(int + frac);

  let f = frac;
  for (let k = d; k > 0 && fracPh[k - 1].ph === "#" && f[k - 1] === "0"; k--) f = f.slice(0, k - 1);
  let i = int.padStart(minInt, "0");
  if (group) i = i.replace(/\B(?=(\d{3})+$)/g, ",");
  const num = i + (dot >= 0 ? "." : "") + f;

  let out = "";
  let done = false;
  for (const t of toks) {
    if (t.lit !== undefined) out += t.lit;
    else if (t.pct) out += "%";
    else if (t.ph) { if (!done) { out += num; done = true; } }
    else if (t.exp) {
      const sign = exponent < 0 ? "-" : t.exp === "+" ? "+" : "";
      out += t.up + sign + String(Math.abs(exponent)).padStart(t.min, "0");
    }
  }
  return { out, zero };
}

export function formatNumber(value, pattern) {
  if (value === null || value === undefined) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (pattern === "General" || !Number.isFinite(value)) return String(value);
  const secs = splitSections(pattern);
  const neg = value < 0;
  let idx = 0;
  if (secs.length === 2 && neg) idx = 1;
  else if (secs.length >= 3) idx = neg ? 1 : value === 0 ? 2 : 0;
  const own = idx === 1 || (secs.length >= 3 && idx === 2) || (secs.length === 2 && neg);
  const { out, zero } = render(Math.abs(value), tokenize(secs[idx]));
  return neg && !own && !zero ? "-" + out : out;
}
