// Insert or delete rows and columns, rewriting formula references to follow the moved cells.
import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";

const REF = /(?<![A-Za-z0-9_.])\$?[A-Za-z]{1,3}\$?\d+(?::\$?[A-Za-z]{1,3}\$?\d+)?(?![A-Za-z0-9_.(])/g;

// Maps one index; null when deleted. delta > 0 inserts, delta < 0 deletes.
function mapIndex(i, at, delta) {
  if (i < at) return i;
  if (delta > 0) return i + delta;
  return i < at - delta ? null : i + delta;
}

// Maps an inclusive span; null when nothing of it is left.
function mapSpan(lo, hi, at, delta) {
  if (delta > 0) return [lo >= at ? lo + delta : lo, hi >= at ? hi + delta : hi];
  const n = -delta;
  const nlo = lo < at ? lo : lo < at + n ? at : lo - n;
  const nhi = hi < at ? hi : hi < at + n ? at - 1 : hi - n;
  return nlo > nhi ? null : [nlo, nhi];
}

const fmt = (p, col, row) => `${p.colAbs ? "$" : ""}${colName(col)}${p.rowAbs ? "$" : ""}${row + 1}`;

function rewriteRef(text, axis, at, delta) {
  const parts = text.split(":").map((t) => parseAddr(t));
  const pos = parts.map((p) => [p.col, p.row]);
  if (parts.length === 1) {
    const v = mapIndex(pos[0][axis], at, delta);
    if (v === null) return "#REF!";
    pos[0][axis] = v;
    return fmt(parts[0], pos[0][0], pos[0][1]);
  }
  const span = mapSpan(Math.min(pos[0][axis], pos[1][axis]), Math.max(pos[0][axis], pos[1][axis]), at, delta);
  if (!span) return "#REF!";
  const rev = pos[0][axis] > pos[1][axis];
  pos[0][axis] = span[rev ? 1 : 0];
  pos[1][axis] = span[rev ? 0 : 1];
  return parts.map((p, k) => fmt(p, pos[k][0], pos[k][1])).join(":");
}

function rewriteFormula(raw, axis, at, delta) {
  // Split on string literals so only code outside them is touched.
  return raw.replace(/"(?:[^"]|"")*"|[^"]+|"/g, (seg) =>
    seg[0] === "\"" ? seg : seg.replace(REF, (m) => rewriteRef(m, axis, at, delta)));
}

function apply(sheet, axis, at, delta) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const p = parseAddr(addr);
    const pos = [p.col, p.row];
    const v = mapIndex(pos[axis], at, delta);
    if (v === null) continue;
    pos[axis] = v;
    next.set(toAddr(pos[0], pos[1]), raw[0] === "=" ? rewriteFormula(raw, axis, at, delta) : raw);
  }
  sheet.cells = next;
}

export const insertRows = (sheet, at, count = 1) => apply(sheet, 1, at - 1, count);
export const deleteRows = (sheet, at, count = 1) => apply(sheet, 1, at - 1, -count);
export const insertCols = (sheet, at, count = 1) => apply(sheet, 0, colIndex(at), count);
export const deleteCols = (sheet, at, count = 1) => apply(sheet, 0, colIndex(at), -count);
