// CSV import and export for sheets.
import { createSheet, setCell, cellAddrs } from "./sheet.mjs";
import { parseAddr, toAddr } from "./addr.mjs";

const text = (v) => (v == null ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));

const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values = null) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    rows = Math.max(rows, p.row + 1);
    cols = Math.max(cols, p.col + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a)) : sheet.cells.get(a) ?? ""));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(src) {
  const n = { ",": 0, ";": 0, "\t": 0 };
  let q = false;
  for (const ch of src) {
    if (ch === "\"") q = !q;
    else if (!q && (ch === "\n" || ch === "\r")) break;
    else if (!q && ch in n) n[ch]++;
  }
  let best = ",";
  for (const d of [";", "\t"]) if (n[d] > n[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const delim = options.delimiter ?? detectDelimiter(src);
  const rows = [];
  let row = [], field = "", line = 1, i = 0, pending = false;
  while (i < src.length) {
    const ch = src[i];
    if (ch === "\"" && field === "") {
      const startLine = line;
      i++;
      for (;;) {
        if (i >= src.length) throw new Error(`unclosed quote at line ${startLine}`);
        const c = src[i++];
        if (c === "\"") {
          if (src[i] === "\"") { field += "\""; i++; } else break;
        } else {
          if (c === "\n") line++;
          field += c;
        }
      }
      pending = true;
    } else if (ch === delim) {
      row.push(field); field = ""; pending = true; i++;
    } else if (ch === "\n" || ch === "\r") {
      if (ch === "\r" && src[i + 1] === "\n") i++;
      i++; line++;
      row.push(field); rows.push(row); row = []; field = ""; pending = false;
    } else {
      field += ch; pending = true; i++;
    }
  }
  if (pending || field !== "" || row.length) { row.push(field); rows.push(row); }
  const sheet = createSheet();
  rows.forEach((fields, r) => fields.forEach((f, c) => {
    setCell(sheet, toAddr(c, r), f[0] === "=" && !options.formulas ? "'" + f : f);
  }));
  return sheet;
}
